def startTest(self, test):
    super(TextTestResult, self).startTest(test)
    if self.showAll:
        self.stream.write(self.getDescription(test))
        self.stream.write(" ... ")
        self.stream.flush()
        self._newline = False

def _write_status(self, test, status):
    is_subtest = isinstance(test, _SubTest)
    if is_subtest or self._newline:
        if not self._newline:
            self.stream.writeln()
        if is_subtest:
            self.stream.write("  ")
        self.stream.write(self.getDescription(test))
        self.stream.write(" ... ")
    self.stream.writeln(status)
    self.stream.flush()
    self._newline = True

def addSubTest(self, test, subtest, err):
    if err is not None:
        if self.showAll:
            if issubclass(err[0], subtest.failureException):
                self._write_status(subtest, "FAIL")
            else:
                self._write_status(subtest, "ERROR")
        elif self.dots:
            if issubclass(err[0], subtest.failureException):
                self.stream.write('F')
            else:
                self.stream.write('E')
            self.stream.flush()
    super(TextTestResult, self).addSubTest(test, subtest, err)

def addSuccess(self, test):
    super(TextTestResult, self).addSuccess(test)
    if self.showAll:
        self._write_status(test, "ok")
    elif self.dots:
        self.stream.write('.')
        self.stream.flush()

def addError(self, test, err):
    super(TextTestResult, self).addError(test, err)
    if self.showAll:
        self._write_status(test, "ERROR")
    elif self.dots:
        self.stream.write('E')
        self.stream.flush()

def addFailure(self, test, err):
    super(TextTestResult, self).addFailure(test, err)
    if self.showAll:
        self._write_status(test, "FAIL")
    elif self.dots:
        self.stream.write('F')
        self.stream.flush()

def addSkip(self, test, reason):
    super(TextTestResult, self).addSkip(test, reason)
    if self.showAll:
        self._write_status(test, "skipped {0!r}".format(reason))
    elif self.dots:
        self.stream.write("s")

@contextlib.contextmanager
def testPartExecutor(self, test_case, subTest=False):
    old_success = self.success
    self.success = True
    try:
        yield
    except KeyboardInterrupt:
        raise
    except SkipTest as e:
        self.success = False
        _addSkip(self.result, test_case, str(e))
    except _ShouldStop:
        pass
    except:
        exc_info = sys.exc_info()
        if self.expecting_failure:
            self.expectedFailure = exc_info
        else:
            self.success = False
            if subTest:
                self.result.addSubTest(test_case.test_case, test_case, exc_info)
            else:
                _addError(self.result, test_case, exc_info)
        # explicitly break a reference cycle:
        # exc_info -> frame -> exc_info
        exc_info = None
    else:
        if subTest and self.success:
            self.result.addSubTest(test_case.test_case, test_case, None)
